/** "Files matching “{query}”": Heading over the results of a search in Files: every file and folder whose name or place holds the words searched for. {query} is what was searched for. Write the quotes in your language's style. */
fun S.appFilesResultsTitle(query: String): UiText =
    UiText.Res(R.string.app_files_results_title, listOf(query))

/** "Search files": Placeholder and screen-reader name of the search field at the top of Files (on a phone held upright): it finds files and folders by name. */
fun S.appFilesSearchField(): UiText =
    UiText.Res(R.string.app_files_search_field)

/** "The device didn't answer the search.": Shown in place of the results of a search in Files when the device answered with an error without saying why (when it says why, its own words are shown instead). A Try again button follows. */
fun S.appFilesSearchNoAnswer(): UiText =
    UiText.Res(R.string.app_files_search_no_answer)

/** "This device can't search its files yet. Update it in Settings.": Shown in place of the results of a search in Files when the device's software is too old to search its files. Settings is the app's section (common.settings), where the device is updated. */
fun S.appFilesSearchTooOld(): UiText =
    UiText.Res(R.string.app_files_search_too_old)

/** "The search didn't reach the device. Check the connection and try again.": Shown in place of the results of a search in Files when the request couldn't be sent or got no answer. A Try again button follows. */
fun S.appFilesSearchUnreached(): UiText =
    UiText.Res(R.string.app_files_search_unreached)

/** "Searching…": Shown with a spinner while a search in Files waits for the device's results. */
fun S.appFilesSearching(): UiText =
    UiText.Res(R.string.app_files_searching)

/** "The selection is in an upload-only folder and cannot be deleted": Short message (toast) at the top of Files when Delete is tapped on the selection bar while something selected is in an upload-only folder (nothing in such a folder can be deleted). No full stop in English. */
fun S.appFilesSelectionUploadOnly(): UiText =
    UiText.Res(R.string.app_files_selection_upload_only)

/** "Could not create share link": Short message (toast) at the top of Files when Share (on the selection bar) failed: the device didn't make a link to the selected files and folders. */
fun S.appFilesShareLinkFailed(): UiText =
    UiText.Res(R.string.app_files_share_link_failed)

/** "Its photos and videos go back to Images, and are tagged - and searched for faces, if face recognition is on - in the background.": Text of the question app.files.show_title: what showing the folder in Images again does. Images is the photo section (app.shell.section_images). */
fun S.appFilesShowMessage(): UiText =
    UiText.Res(R.string.app_files_show_message)

/** "Show “{name}” in Images?": Title of the question asked before showing a folder kept out of Images there again (from Show in Images in Files). {name} is the folder's name. The explanation (app.files.show_message) follows. Images is the photo section (app.shell.section_images). Write the quotes in your language's style. */
fun S.appFilesShowTitle(name: String): UiText =
    UiText.Res(R.string.app_files_show_title, listOf(name))

/** "A to Z": Files, the View options menu (the button beside the path field): shown under Name while the files and folders are in name order from A to Z. */
fun S.appFilesSortAZ(): UiText =
    UiText.Res(R.string.app_files_sort_a_z)

/** "Sort by": Files, the View options menu (the button beside the path field): heading over the orders the files and folders can be in (app.files.sort_name, sort_size, sort_created, sort_modified). Folders always stay above the files. */
fun S.appFilesSortBy(): UiText =
    UiText.Res(R.string.app_files_sort_by)

/** "Date created": Files, the View options menu (the button beside the path field), under Sort by: orders the files by when they were created. Picked again, the order reverses (newest or oldest first). */
fun S.appFilesSortCreated(): UiText =
    UiText.Res(R.string.app_files_sort_created)

/** "Largest first": Files, the View options menu (the button beside the path field): shown under Size while the largest files come first. */
fun S.appFilesSortLargest(): UiText =
    UiText.Res(R.string.app_files_sort_largest)

/** "Date modified": Files, the View options menu (the button beside the path field), under Sort by: orders the files by when they last changed. Picked again, the order reverses (newest or oldest first). */
fun S.appFilesSortModified(): UiText =
    UiText.Res(R.string.app_files_sort_modified)

/** "Name": Files, the View options menu (the button beside the path field), under Sort by: orders the files and folders by name. Picked again, the order reverses (from A to Z, or Z to A). */
fun S.appFilesSortName(): UiText =
    UiText.Res(R.string.app_files_sort_name)

/** "Newest first": Files, the View options menu (the button beside the path field): shown under Date created or Date modified while the most recent files come first. */
fun S.appFilesSortNewest(): UiText =
    UiText.Res(R.string.app_files_sort_newest)

/** "Oldest first": Files, the View options menu (the button beside the path field): shown under Date created or Date modified while the least recent files come first. */
fun S.appFilesSortOldest(): UiText =
    UiText.Res(R.string.app_files_sort_oldest)

/** "Size": Files, the View options menu (the button beside the path field), under Sort by: orders the files by size. Picked again, the order reverses (largest or smallest first). */
fun S.appFilesSortSize(): UiText =
    UiText.Res(R.string.app_files_sort_size)

/** "Smallest first": Files, the View options menu (the button beside the path field): shown under Size while the smallest files come first. */
fun S.appFilesSortSmallest(): UiText =
    UiText.Res(R.string.app_files_sort_smallest)

/** "Z to A": Files, the View options menu (the button beside the path field): shown under Name while the files and folders are in name order from Z to A. */
fun S.appFilesSortZA(): UiText =
    UiText.Res(R.string.app_files_sort_z_a)

/** "Sorted by {key}, {order}": Files: said by VoiceOver or TalkBack after the order changes; never shown, so capital letters inside it don't matter. {key} is the order's name in the menu (app.files.sort_name, sort_size, sort_created or sort_modified) and {order} the words shown under it (app.files.sort_a_z, sort_largest, sort_newest...). */
fun S.appFilesSorted(key: String, order: String): UiText =
    UiText.Res(R.string.app_files_sorted, listOf(key, order))

/** "Unexpected response": Error shown when the device answered with something other than what was asked for: the line under the path field in Files (the folder couldn't be listed), and the Share as Gallery dialog (Android). */
fun S.appFilesUnexpectedResponse(): UiText =
    UiText.Res(R.string.app_files_unexpected_response)

/** "Upload failed: {detail}": Short message (toast) at the top of Files when a file picked on the phone couldn't be uploaded into the folder shown. {detail} is the reason: the device's own words, or the app's or the phone's. */
fun S.appFilesUploadFailed(detail: String): UiText =
    UiText.Res(R.string.app_files_upload_failed, listOf(detail))

/** "Upload only": Title of the explanation shown when the lock of an upload-only folder or file is tapped in Files, and screen-reader name of the lock badge on a folder's tile in the grid. Upload only: nothing in the folder can be deleted, and uploading a file again keeps its older version. */
fun S.appFilesUploadOnly(): UiText =
    UiText.Res(R.string.app_files_upload_only)

/** "This is in an upload-only folder: it can't be deleted, and uploading it again keeps its older version. The lock on the folder changes it.": Explanation shown (title app.files.upload_only) when the lock on a file's row in Files is tapped: the file is inside an upload-only folder. */
fun S.appFilesUploadOnlyFileInfo(): UiText =
    UiText.Res(R.string.app_files_upload_only_file_info)

/** "Uploading {done} of {total}…": Files: the line above the bottom bar while the files picked to upload into the folder are being sent, with Cancel beside it. {done} is the number of the file being sent, {total} how many were picked. */
fun S.appFilesUploading(done: Int, total: Int): UiText =
    UiText.Res(R.string.app_files_uploading, listOf(done, total))

/** "Nothing in this folder takes up space.": Shown in Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first. in place of the rows when nothing in the folder takes space: it is empty, or holds only empty folders. */
fun S.appFilesUsageEmpty(): UiText =
    UiText.Res(R.string.app_files_usage_empty)

/** "Couldn't find out how much space this folder takes.": Shown in Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first. in place of the rows when the device didn't answer (no connection, no reply) and gave no reason of its own; a Try again button (common.try_again) follows. */
fun S.appFilesUsageFailed(): UiText =
    UiText.Res(R.string.app_files_usage_failed)

/** "Your device needs an update to show how much space folders take.": Shown in Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first. in place of the rows when the device's software is too old to say how much space folders take. */
fun S.appFilesUsageNeedsUpdate(): UiText =
    UiText.Res(R.string.app_files_usage_needs_update)

/** "Sizes are counted file by file: a file kept in two places counts twice, though the device stores it once. Thumbnails and encryption aren't counted, so the totals won't match the storage bar.": Footnote under the rows of Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first.: the sizes are each file's own size. Content stored at two paths is kept once on the device but counted at both; thumbnails (the small previews) and the space encryption adds aren't counted. So the totals differ from the bar that shows how full the device's storage is (in the menu and Settings). */
fun S.appFilesUsageNote(): UiText =
    UiText.Res(R.string.app_files_usage_note)

/** "{size} · {share}": Line under a file's or folder's name in Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first., by its bar. {size} is its size, already formatted with its unit (1.2 GB); {share} is the row's share of the folder, already formatted as a percentage (45%), or app.files.usage_share_small when it is under one per cent. Keep the middle dot unless your language separates such values otherwise. */
fun S.appFilesUsageRow(size: String, share: String): UiText =
    UiText.Res(R.string.app_files_usage_row, listOf(size, share))

/** "{name}, {size}, {share} of this folder": Screen-reader name of a row in Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first.. {name} is the file's or folder's name; {size} its size, already formatted with its unit (1.2 GB); {share} is the row's share of the folder, already formatted as a percentage (45%), or app.files.usage_share_small when it is under one per cent. When the folder takes no space at all, {share} is 0%. */
fun S.appFilesUsageRowLabel(name: String, size: String, share: String): UiText =
    UiText.Res(R.string.app_files_usage_row_label, listOf(name, size, share))

/** "under 1%": In Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first.: the share of a file or folder that takes some space but less than one per cent of the folder, in place of a percentage like 45%. Write the per cent sign as your language does. Starts in lowercase in English: it is a value, and it is also put inside app.files.usage_row_label. */
fun S.appFilesUsageShareSmall(): UiText =
    UiText.Res(R.string.app_files_usage_share_small)

/** "This folder: {size} in {count} files" (one: "This folder: {size} in {count} file"): First line above the rows of Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first. {size} is the folder's whole size, older versions included (the base of the rows' percentages), already formatted with its unit (1.2 TB); {count} is how many files are under it, at any depth. */
fun S.appFilesUsageTotal(size: String, count: Int): UiText =
    UiText.Plural(R.plurals.app_files_usage_total, count, listOf(size, count))

/** "{size} of it in older versions": Second line above the rows of Files' Storage view (the third view, next to List and Grid), which shows what takes space in the open folder: each file and folder in it with a bar, its share of the folder and its size, largest first., under app.files.usage_total, shown only when the folder keeps older versions of files (in upload-only folders). {size} is how much of the folder's size they take, already formatted with its unit (3.4 GB). */
fun S.appFilesUsageVersions(size: String): UiText =
    UiText.Res(R.string.app_files_usage_versions, listOf(size))

/** "Current": First row of the Versions list (app.files.versions_title): the file as it is now, with its size at the right. A tap opens it. */
fun S.appFilesVersionCurrent(): UiText =
    UiText.Res(R.string.app_files_version_current)

/** "Could not fetch that version": Short message (toast) at the top of Files when an older version of a file was tapped in the Versions list and the device refused to send it. */
fun S.appFilesVersionOpenFailed(): UiText =
    UiText.Res(R.string.app_files_version_open_failed)

/** "Replaced {date}": A row of the Versions list (app.files.versions_title): an older version of the file and when the next upload replaced it, with its size at the right. A tap opens it. {date} is the date and time, written by the phone for the app's language (for example 5 Oct 2026, 14:03), or a dash when unknown. */
fun S.appFilesVersionReplaced(date: String): UiText =
    UiText.Res(R.string.app_files_version_replaced, listOf(date))

/** "The file is in an upload-only folder, so each upload to this path kept the one before it.": Explanation at the top (Android) or the foot (iPhone) of the Versions list (app.files.versions_title). Path means the file's place and name on the device. */
fun S.appFilesVersionsExplain(): UiText =
    UiText.Res(R.string.app_files_versions_explain)

/** "Versions of {name}": Title of the list of a file's older versions, opened from the badge with a clock and a number on the file in Files. {name} is the file's name. */
fun S.appFilesVersionsTitle(name: String): UiText =
    UiText.Res(R.string.app_files_versions_title, listOf(name))

/** "Video": Screen-reader name of the play badge on a video's thumbnail, in the grid of tiles in Files and in the results of a search in Files. */
fun S.appFilesVideo(): UiText =
    UiText.Res(R.string.app_files_video)

/** "Grid": Files, the View options menu (the button beside the path field): shows the folder as a grid of tiles (thumbnails and file icons). */
fun S.appFilesViewGrid(): UiText =
    UiText.Res(R.string.app_files_view_grid)

/** "List": Files, the View options menu (the button beside the path field): shows the folder as a list, a row per file or folder. */
fun S.appFilesViewList(): UiText =
    UiText.Res(R.string.app_files_view_list)

/** "View options": Files: accessibility name of the button beside the path field that opens a menu: the folder as a list or a grid (app.files.view_list, app.files.view_grid), and the order of its files and folders (app.files.sort_by). */
fun S.appFilesViewOptions(): UiText =
    UiText.Res(R.string.app_files_view_options)

/** "Storage": Third choice of Files' view menu, next to List (app.files.view_list) and Grid (app.files.view_grid): shows the Storage view, what takes space in the open folder. Use your language's word for storage space; a short word. */
fun S.appFilesViewStorage(): UiText =
    UiText.Res(R.string.app_files_view_storage)
